/**
 * Comments on a record, with their replies (`design/components/comment-thread.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/comment-thread.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, ViewEncapsulation, input } from '@angular/core'

import {
  MEMBER_PROVIDERS,
  SlotOutlet,
  SlotTemplate,
  getters,
  provideOwner,
  useMember,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/structure/comment-thread.module.css'

export interface CommentThreadMessages {
  edited: string
  replies: string
}

/** Comments on a record, with their replies: the inputs it takes, by the React member's prop names. */
export interface CommentThreadProps {
  /**
   * Names the list for a reader: "Comments", not "Thread".
   */
  label: string
  /**
   * The words the member writes itself, for every comment in the thread. English by default.
   */
  messages?: CommentThreadMessages
}

/** What CommentThread hands its compound parts. */
export interface CommentThreadOwner {
  readonly messages: Exclude<CommentThreadProps['messages'], undefined>
}

/** Comments on a record, with their replies. */
@Component({
  selector: 'pm-comment-thread',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS, provideOwner('CommentThread')],
  imports: [SlotOutlet, SlotTemplate],
  // prettier-ignore
  template: `<ng-template pmSlot="default" [pmSlotOf]="$"><ng-content /></ng-template>
<ol
[attr.class]="e1()"
role="list"
[attr.aria-label]="e2()"
data-member="comment-thread"
><ng-container [pmSlotOutlet]="'default'" [pmSlotOf]="$" /></ol>`,
})
export class CommentThread {
  /**
   * Names the list for a reader: "Comments", not "Thread".
   */
  readonly label = input.required<CommentThreadProps['label']>()
  /**
   * The words the member writes itself, for every comment in the thread. English by default.
   */
  readonly messages = input<
    Exclude<CommentThreadProps['messages'], undefined>,
    CommentThreadProps['messages']
  >((() => ({ edited: 'Edited', replies: 'Replies' }))(), {
    transform: (value: CommentThreadProps['messages']) =>
      value === undefined ? (() => ({ edited: 'Edited', replies: 'Replies' }))() : value,
  })
  protected readonly $ = useMember({
    events: [],
    props: { label: () => this.label(), messages: () => this.messages() },
  })
  protected readonly $p = this.$.props

  constructor() {
    this.$.owner = getters<CommentThreadOwner>({ messages: () => this.$p.messages })
  }

  protected e1() {
    return styles.thread
  }

  protected e2() {
    return this.$p.label
  }
}
